\section{Notation}
\label{sec:notation}

\begin{table}[htbp]
\centering
\small
\caption{Key symbols and abbreviations used throughout the paper.}
\label{tab:notation}
\resizebox{\columnwidth}{!}{%
\begin{tabular}{ll}
\toprule
\textbf{Symbol} & \textbf{Description} \\
\midrule
$\Kempirical$ & Empirical discrimination boundary (operational, feature-dependent) \\
$\Ktheory$ & Theoretical discrimination boundary (feature-independent upper limit) \\
$K^*_{\text{neural}}$ & $\Kempirical$ measured with neural probe (frozen encoder + MLP) \\
$K^*_{\text{binary}}$ & $\Kempirical$ of binary (human vs.\ machine) detectors \\
$\theta$ & AUC decision threshold (default 0.60) \\
$\auc$ & Area Under the ROC Curve (pairwise, between adjacent depths) \\
JSD & Jensen--Shannon Divergence (token-level, between adjacent depths) \\
OBD & Ordinal Binary Decomposition (classifier architecture) \\
LOFO & Leave-One-Family-Out cross-validation \\
PELT & Pruned Exact Linear Time changepoint detection \\
\bottomrule
\end{tabular}}
\end{table}

